Translate the following GNU C++11 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <iostream>
#include <cmath>
#include <functional>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    long long x, y, n;
    cin >> x >> y >> n;

    long double target = static_cast<long double>(x) / y;

    auto minimize = [&](const function<pair<long long>(long long)>& choose, 
                        long long& best_a, long long& best_b, long double& best_diff) {
        for (long long b = 1; b <= n; ++b) {
            long long a = choose(b);
            long double diff = abs(target - static_cast<long double>(a) / b);
            if (diff < best_diff) {
                best_diff = diff;
                best_a = a;
                best_b = b;
            }
        }
    };

    long long best_a = 1, best_b = 1;
    long double best_diff = 1e30;

    if (y <= 1) {
        cout << x << '/' << y;
        return 0;
    }

    minimize([target](long long b) { return static_cast<long long>(floor(target * b)); },
             best_a, best_b, best_diff);
    minimize([target](long long b) { return static_cast<long long>(ceil(target * b)); },
             best_a, best_b, best_diff);

    cout << best_a << '/' << best_b;
    return 0;
}
</original_code>
